const termino = $fromAI('termino_busqueda', 'Producto o término a buscar en la tienda online', 'string');
const API_KEY = '4d8cfb14fba5451c875ac515fa047f9b';

if (!termino || !String(termino).trim()) {
  return '⚠️ Debes enviar un término de búsqueda válido.';
}

if (API_KEY === 'CONFIGURAR_AQUI_NUEVA_AGENT_OPS_API_KEY') {
  return '⚠️ Configura la nueva AGENT_OPS_API_KEY dentro del nodo TOOL_BuscarProductos antes de usar esta herramienta.';
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://tus-aguacates.vercel.app/api/agent/products',
    qs: { search: termino, limit: 5, active_only: true },
    headers: {
      'x-agent-key': API_KEY,
      'Accept': 'application/json'
    },
    json: true
  });

  return JSON.stringify(response);
} catch (error) {
  return '❌ Error consultando catálogo online: ' + error.message;
}
